import type { PersonInput } from "@/lib/schema";

/**
 * Principal investigators and lead authors named by the subtype-page landmark trials (trials-subtypes-wave.ts) and key
 * papers (papers-subtypes-wave.ts) who had no person record (18 Sept 2026). Built by listing the first author of every
 * paper in that wave and the primary-publication first author of every trial in it, then checking each against existing
 * people by name and `aka`. Public professional information only; each record states what the person is known for and
 * links back to the trial and paper records that name them (`trials`, `keyPapers`). The institution is linked only where
 * the current affiliation is certain and an institution record exists; otherwise it is left out. Each trial or paper
 * record gained a `people` entry so the person is reachable. Registered in src/data/index.ts; `tldrZh` is folded by
 * scripts/fold-zh.ts.
 */
const asOf = "2026-09-18";
type P = Omit<PersonInput, "kind" | "asOf">;
const pubmed = (q: string) => ({ label: "PubMed", url: `https://pubmed.ncbi.nlm.nih.gov/?term=${encodeURIComponent(q)}` });
const p = (x: P): PersonInput => ({ kind: "person", asOf, institutions: x.institutionId ? [x.institutionId] : [], profiles: [pubmed(`${x.name.split(" ").pop()}[Author]`)], ...x });

